<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $data = isset( $args ) ? $args : sd_communities_template_data(); $result = $data['result']; ?><section class="sd-community-directory"><header class="sd-page-heading"><span class="sd-eyebrow"><?php esc_html_e( 'Find your people', 'social-discovery' ); ?></span><h1><?php esc_html_e( 'Communities', 'social-discovery' ); ?></h1><p><?php esc_html_e( 'Explore public spaces and find communities that fit your interests.', 'social-discovery' ); ?></p></header><form class="sd-community-toolbar" method="get"><label><span class="screen-reader-text"><?php esc_html_e( 'Search communities', 'social-discovery' ); ?></span><input type="search" name="community_search" value="<?php echo esc_attr( $data['search'] ); ?>" placeholder="<?php esc_attr_e( 'Search communities', 'social-discovery' ); ?>"></label><select name="community_sort" aria-label="<?php esc_attr_e( 'Sort communities', 'social-discovery' ); ?>"><option value="active" <?php selected( $data['sort'], 'active' ); ?>><?php esc_html_e( 'Recently active', 'social-discovery' ); ?></option><option value="newest" <?php selected( $data['sort'], 'newest' ); ?>><?php esc_html_e( 'Newest', 'social-discovery' ); ?></option><option value="popular" <?php selected( $data['sort'], 'popular' ); ?>><?php esc_html_e( 'Most members', 'social-discovery' ); ?></option><option value="alphabetical" <?php selected( $data['sort'], 'alphabetical' ); ?>><?php esc_html_e( 'Alphabetical', 'social-discovery' ); ?></option></select><button class="sd-button" type="submit"><?php esc_html_e( 'Search', 'social-discovery' ); ?></button></form><?php if ( ! sd_groups_available() ) : ?><div class="sd-empty-state"><h2><?php esc_html_e( 'Communities are not available yet', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'Enable the BuddyPress Groups component to manage communities here.', 'social-discovery' ); ?></p></div><?php elseif ( empty( $result['groups'] ) ) : ?><div class="sd-empty-state"><h2><?php esc_html_e( 'No communities found', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'Try another search or check back as new communities are created.', 'social-discovery' ); ?></p></div><?php else : ?><div class="sd-community-grid sd-community-layout-<?php echo esc_attr( sd_get_option( 'sd_communities_layout' ) ); ?>"><?php foreach ( $result['groups'] as $group ) { get_template_part( 'template-parts/communities/group-card', null, array( 'group' => $group ) ); } ?></div><?php endif; ?></section>
